window.__texto({"id": "732983242", "paragrafos": [{"c": "identifica", "t": "CONSULTA PÚBLICA N.º 16, DE 16 DE SETEMBRO DE 2026 (*)"}, {"c": "ementa", "t": "Proposta de Requisitos de Avaliação da Conformidade para Sustentabilidade de Produtos e Serviços - Selo Verde Brasil."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - Inmetro, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinados com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando o que consta no Processo SEI nº 0052600.001887/2026-35, resolve:"}, {"c": "dou-paragraph", "t": "Art. 1º Fica disponível, no sítio eletrônico www.inmetro.gov.br, a proposta de texto de Portaria Inmetro, que aprova os Requisitos de Avaliação da Conformidade para Sustentabilidade de Produtos e Serviços."}, {"c": "dou-paragraph", "t": "Art. 2º Fica aberto, a partir da data da publicação desta Consulta Pública no Diário Oficial da União, o prazo de 30 (trinta) dias para que sejam apresentadas sugestões e críticas relativas ao texto proposto."}, {"c": "dou-paragraph", "t": "Art. 3º As críticas e sugestões devem ser apresentadas na Portal Brasil Participativo contida na página eletrônica: https://brasilparticipativo.presidencia.gov.br/."}, {"c": "dou-paragraph", "t": "§ 1º As críticas e sugestões que não forem apresentadas conforme previsto no caput não serão consideradas como válidas para efeito da consulta pública e serão devolvidas ao demandante."}, {"c": "dou-paragraph", "t": "§ 2º O demandante que tiver dificuldade em utilizar o Portal pode solicitar ajuda através dos canais de atendimento do Inmetro, disponíveis na página eletrônica: https://www.gov.br/inmetro/pt-br/canais_atendimento/ouvidoria/faca-sua-manifestacao."}, {"c": "dou-paragraph", "t": "Art. 4º Findo o prazo fixado no art. 2º desta Portaria, o Inmetro se articulará com as entidades que tenham manifestado interesse na matéria, para que indiquem representantes nas discussões posteriores, visando à consolidação do texto final."}, {"c": "dou-paragraph", "t": "Art. 5º Esta de Consulta Pública entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "dou-paragraph", "t": "PORTARIA Nº XXX, DE XX DE XXXXXXXX DE 2026"}, {"c": "dou-paragraph", "t": "Aprova os Requisitos de Avaliação da Conformidade para Sustentabilidade de Produtos e Serviços - Selo Verde Brasil."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - INMETRO, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinados com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando o Decreto nº 12.063 de 17 de junho de 2024, a Consulta Pública Inmetro n° XX, de XX de XXXXX de 2026, publicada no DOU de XX de XXXXX de 2026, seção 1, páginas XX a XX, e o que consta no Processo SEI nº 0052600.001887/2026-35, resolve:"}, {"c": "dou-paragraph", "t": "Objeto e âmbito de aplicação"}, {"c": "dou-paragraph", "t": "Art. 1º Ficam aprovados os Requisitos de Avaliação da Conformidade e as Especificações para o Selo de Identificação da Conformidade para Sustentabilidade de Produtos e Serviços - Selo Verde Brasil, fixados, respectivamente, nos Anexos I e II desta Portaria."}, {"c": "dou-paragraph", "t": "§ 1º A avaliação da conformidade quanto à sustentabilidade de produtos e serviços, de caráter voluntário, por meio do mecanismo de certificação, deve ser realizada por Organismo de Certificação de Produto - OCP, estabelecido no Brasil e acreditado pelo Inmetro, consoante os Requisitos ora aprovados."}, {"c": "dou-paragraph", "t": "§ 2º Aplicam-se os presentes Requisitos à Sustentabilidade dos Produtos e Serviços conforme previstos em cada Anexo Específico do Anexo desta Portaria."}, {"c": "dou-paragraph", "t": "§ 3º Encontram-se excluídos do escopo de abrangência desses Requisitos produtos e serviços importados."}, {"c": "dou-paragraph", "t": "Art. 2º Não compete ao Inmetro o exercício do poder de polícia administrativa quanto ao objeto, cabendo, exclusivamente, a supervisão quanto ao uso da marca, tendo por foco o cumprimento das regras de Avaliação da Conformidade."}, {"c": "dou-paragraph", "t": "Vigência"}, {"c": "dou-paragraph", "t": "Art. 3º Esta Portaria entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDRE OLIVEIRA BRITO"}, {"c": "dou-paragraph", "t": "ANEXO I"}, {"c": "dou-paragraph", "t": "REQUISITOS DE AVALIAÇÃO DA CONFORMIDADE PARA SUSTENTABILIDADE DE PRODUTOS E SERVIÇOS"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Este documento estabelece os procedimentos de avaliação da conformidade de produtos e serviços, com foco na sustentabilidade, através do mecanismo de certificação, visando assegurar atributos declarados de sustentabilidade, inclusive ambientais, sociais, econômicos e de governança."}, {"c": "dou-paragraph", "t": "1.1 Agrupamento para efeito de certificação"}, {"c": "dou-paragraph", "t": "Para a certificação do objeto, aplica-se o conceito de família ou modelo ou escopo de serviço, conforme definido nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "2. SIGLAS"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotadas as siglas que constam nos Anexos Específicos deste RAC, complementadas pelas contidas nos documentos citados no item 3."}, {"c": "dou-paragraph", "t": "3. DOCUMENTOS"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotados os Documentos Complementares do RGCP, os relacionados nos Anexos Específicos deste RAC, bem como os listados a seguir:"}, {"c": "", "t": "ABNT NBR 20250"}, {"c": "", "t": "Diretrizes gerais de sustentabilidade para produtos e serviços."}, {"c": "", "t": "ABNT NBR ISO 14001"}, {"c": "", "t": "Sistemas de gestão ambiental - Requisitos com orientações para uso."}, {"c": "", "t": "Portaria Inmetro nº 200, de 2021, ou substitutiva."}, {"c": "", "t": "Aprova os Requisitos Gerais de Certificação de Produtos - RGCP"}, {"c": "dou-paragraph", "t": "4. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "São adotadas as definições dos documentos estabelecidos no item 3, bem como aquelas estabelecidas nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "5. MECANISMO DE AVALIAÇAO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "O mecanismo de avaliação da conformidade para Sustentabilidade de Produtos e Serviços é a certificação."}, {"c": "dou-paragraph", "t": "6. ETAPAS DA AVALIAÇAO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "Este RAC adota o Modelo Especial de Certificação (MEC), que pode compreender, conforme previsto em cada Anexo Específico, avaliação inicial, avaliações de manutenção periódicas e recertificação."}, {"c": "dou-paragraph", "t": "A avaliação inicial e a avaliação de recertificação podem incluir auditoria do Sistema de Gestão Ambiental (SGA) do fabricante ou do prestador de serviços, com base na norma ABNT NBR ISO 14001, ou avaliação do processo produtivo, com base na norma ABNT NBR 20250, ou ensaios em amostras coletadas no fabricante ou combinação de duas ou mais dessas alternativas, conforme definido no respectivo Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "As avaliações de manutenção podem ser realizadas por meio de nova auditoria do Sistema de Gestão Ambiental (SGA) do fabricante ou do prestador de serviços, com base na norma ABNT NBR ISO 14001, ou nova avaliação do processo produtivo, com base na norma ABNT NBR 20250, ou ensaios de amostras coletadas no fabricante ou no comércio para atividades de avaliação da conformidade, ou pela combinação de duas ou mais dessas alternativas, conforme definido no respectivo Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.1 Avaliação Inicial"}, {"c": "dou-paragraph", "t": "6.1.1 Solicitação de Certificação"}, {"c": "dou-paragraph", "t": "O fabricante deve encaminhar uma solicitação formal ao OCP, fornecendo a documentação descrita no RGCP, naquilo que for aplicável, complementado pelo que segue:"}, {"c": "dou-paragraph", "t": "a) documentos referentes ao Sistema de Gestão Ambiental do fabricante, ainda que os mesmos venham necessariamente a ser auditados pelo OCP, como previsto neste documento;"}, {"c": "dou-paragraph", "t": "b) certificado válido emitido com base na edição vigente da norma ISO 14001 ou norma ABNT NBR ISO14001,que abranja o processo produtivo do objeto da certificação, se existente, ou documentação do sistema de gestão aplicável ao objeto, quando exigida;"}, {"c": "dou-paragraph", "t": "c) evidências do atendimento aos requisitos de sustentabilidade previstos em cada Anexo Específico, incluindo matriz de verificação e documentos comprobatórios;"}, {"c": "dou-paragraph", "t": "d) procedimentos de rastreabilidade, cadeia de custódia, controle de fornecedores e tratamento de reclamações;"}, {"c": "dou-paragraph", "t": "e) relatórios de ensaio, inspeção, auditoria, verificação ou estudos técnicos já existentes, quando houver; e"}, {"c": "dou-paragraph", "t": "f) demais documentos necessários ao processo de solicitação, descritos em cada Anexo Específico."}, {"c": "dou-paragraph", "t": "6.1.2 Análise da Solicitação e da Conformidade da Documentação"}, {"c": "dou-paragraph", "t": "Os critérios de análise da solicitação e da conformidade da documentação devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.1.3 Auditoria Inicial do Sistema de Gestão Ambiental e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "6.1.3.1 A Auditoria do SGA deve ser realizada sempre que o modelo de certificação definido em cada Anexo Específico assim o estabelecer independentemente do fabricante ou do prestador de serviço possuir Sistema de Gestão Ambiental certificado com base na norma ISO 14001 ou norma ABNT NBR ISO 14001."}, {"c": "dou-paragraph", "t": "6.1.3.2 De acordo com o MEC adotado, o OCP avalia os documentos e registros do SGA, e realiza auditoria nas dependências do prestador de serviço ou da unidade fabril, com o objetivo de verificar a conformidade do processo produtivo, incluindo instalações e capacitação do pessoal. A auditoria do SGA deve buscar a demonstração objetiva de que o processo produtivo se encontra sistematizado e monitorado de forma eficaz, fornecendo evidências do atendimento aos requisitos de produto ou serviço estabelecidos em cada Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.1.3.3 Registros da conformidade no atendimento desses requisitos devem ser obtidos de forma consistente."}, {"c": "dou-paragraph", "t": "6.1.3.4 A data da visita para a auditoria deve ser agendada em comum acordo com o Fabricante solicitante da certificação."}, {"c": "dou-paragraph", "t": "6.1.3.5 A avaliação do SGA deve ser feita pelo OCP com base na abrangência do processo de certificação e conforme os requisitos da norma ISO 14001 ou norma ABNT NBR ISO 14001, tendo como requisitos mínimos os definidos nas Tabelas 1 e 2 a seguir:"}, {"c": "dou-paragraph", "t": "Tabela 1: Requisitos mínimos de verificação do SGA para fabricantes ou prestadores de serviços com certificação válida na norma ISO 14001 ou norma ABNT NBR ISO 14001"}, {"c": "", "t": "Requisitos mínimos de verificação do SGA"}, {"c": "", "t": "Itens da ISO 14001 / ABNT ISO 14001"}, {"c": "", "t": "Recursos"}, {"c": "", "t": "7.1"}, {"c": "", "t": "Comunicação"}, {"c": "", "t": "7.4.2 / 7.4.3"}, {"c": "", "t": "Informação documentada"}, {"c": "", "t": "7.5.2 / 7.5.3"}, {"c": "", "t": "Planejamento e controle operacionais"}, {"c": "", "t": "8.1"}, {"c": "", "t": "Monitoramento, medição, análise e avaliação"}, {"c": "", "t": "9.1.1 / 9.1.2"}, {"c": "", "t": "Não conformidade e ação corretiva"}, {"c": "", "t": "10.2"}, {"c": "dou-paragraph", "t": "Tabela 2: Requisitos mínimos de verificação do SGA para fabricantes e prestadores de serviço sem certificação na norma ISO 14001 ou norma ABNT NBR ISO 14001"}, {"c": "", "t": "Requisitos mínimos de verificação do SGA"}, {"c": "", "t": "Itens da ISO 14001 / ABNT ISO 14001"}, {"c": "", "t": "Recursos"}, {"c": "", "t": "7.1"}, {"c": "", "t": "Competência"}, {"c": "", "t": "7.2"}, {"c": "", "t": "Conscientização"}, {"c": "", "t": "7.3"}, {"c": "", "t": "Comunicação"}, {"c": "", "t": "7.4.2 / 7.4.3"}, {"c": "", "t": "Informação documentada"}, {"c": "", "t": "7.5.2 / 7.5.3"}, {"c": "", "t": "Planejamento e controle operacionais"}, {"c": "", "t": "8.1"}, {"c": "", "t": "Monitoramento, medição, análise e avaliação"}, {"c": "", "t": "9.1.1 / 9.1.2"}, {"c": "", "t": "Auditoria interna"}, {"c": "", "t": "9.2.1 / 9.2.2"}, {"c": "", "t": "Análise crítica pela direção"}, {"c": "", "t": "9.3"}, {"c": "", "t": "Não conformidade e ação corretiva"}, {"c": "", "t": "10.2"}, {"c": "dou-paragraph", "t": "6.1.3.6 Mesmo mediante a apresentação de certificado válido, segundo a edição vigente da norma ISO 14001 ou norma ABNT NBR ISO 14001, emitido por um OCS acreditado pelo Inmetro ou membro do MLA do IAF ou da Global Accreditation Cooperation Incorporated, para o escopo de acreditação respectivo, o OCP deve proceder à auditoria inicial do SGA na unidade fabril ou do prestador de serviço durante a etapa de avaliação inicial, de acordo com a Tabela 1 deste RAC, com o objetivo de verificar a conformidade do processo produtivo."}, {"c": "dou-paragraph", "t": "6.1.3.6.1 Os certificados, emitidos por um OCS estrangeiro devem estar acompanhados de tradução juramentada no idioma português, quando estes forem emitidos em idioma distinto do inglês ou espanhol. Os demais documentos referentes ao Sistema de Gestão, que estiverem em idioma distinto do inglês ou do espanhol, devem estar traduzidos para o português."}, {"c": "dou-paragraph", "t": "6.1.3.7 Durante a auditoria, o Fabricante solicitante da certificação deve colocar à disposição do OCP todos os documentos correspondentes à certificação do Sistema de Gestão Ambiental com base na edição vigente da norma ISO 14001 ou norma ABNT NBR ISO 14001 e apresentar os registros do processo produtivo onde conste claramente a identificação do objeto da certificação. O OCP deve analisar a documentação pertinente para assegurar que os requisitos descritos na Tabela 2 do item 6.1.3.1 foram atendidos."}, {"c": "dou-paragraph", "t": "6.1.3.8 A Avaliação do Processo Produtivo deve ser feita pelo OCP com base na abrangência do processo de certificação e conforme os requisitos estabelecidos com base na norma ABNT NBR 20250, tendo como requisitos mínimos os definidos na Tabela 3 a seguir."}, {"c": "dou-paragraph", "t": "Nota: A norma ABNT NBR 20250 estabelece diretrizes, mas, para efeito deste RAC, elas são adotadas e fixadas como requisitos e que devem ser cumpridos pelo Fabricante."}, {"c": "dou-paragraph", "t": "Tabela 3: Requisitos mínimos de Avaliação do Processo Produtivo para fabricantes e prestadores de serviço com base na norma ABNT NBR 20250."}, {"c": "", "t": "Requisitos de Avaliação do Processo Produtivo"}, {"c": "", "t": "Itens da ABNT NBR 20250"}, {"c": "", "t": "Emissão de efluentes líquidos"}, {"c": "", "t": "5.1"}, {"c": "", "t": "Emissões para a atmosfera"}, {"c": "", "t": "5.2"}, {"c": "", "t": "Uso da energia"}, {"c": "", "t": "5.3"}, {"c": "", "t": "Geração de resíduos sólidos"}, {"c": "", "t": "5.4"}, {"c": "", "t": "Emissão de substâncias tóxicas"}, {"c": "", "t": "5.5"}, {"c": "", "t": "Uso de recursos naturais"}, {"c": "", "t": "5.6"}, {"c": "", "t": "Uso da biodiversidade"}, {"c": "", "t": "5.7"}, {"c": "", "t": "Assédio"}, {"c": "", "t": "6.1"}, {"c": "", "t": "Condições de trabalho"}, {"c": "", "t": "6.2"}, {"c": "", "t": "Direitos trabalhistas"}, {"c": "", "t": "6.3"}, {"c": "", "t": "Diversidade, equidade e inclusão"}, {"c": "", "t": "6.4"}, {"c": "", "t": "Geração de trabalho e renda"}, {"c": "", "t": "6.5"}, {"c": "", "t": "Desenvolvimento local"}, {"c": "", "t": "6.6"}, {"c": "", "t": "Respeito as comunidades locais e comunidades tradicionais"}, {"c": "", "t": "6.7"}, {"c": "", "t": "Demanda por fornecimento local"}, {"c": "", "t": "7.1"}, {"c": "", "t": "Desenvolvimento regional"}, {"c": "", "t": "7.2"}, {"c": "", "t": "Inclusão de micro, pequenas e médias empresas na cadeia de valor"}, {"c": "", "t": "7.3"}, {"c": "", "t": "Proteção de valor"}, {"c": "", "t": "7.4"}, {"c": "", "t": "Qualidade do produto ou serviço"}, {"c": "", "t": "7.5"}, {"c": "", "t": "Demanda por recursos"}, {"c": "", "t": "7.6"}, {"c": "", "t": "Conformidade legal e respeito pelas convenções internacionais de comportamento"}, {"c": "", "t": "7.7"}, {"c": "", "t": "Viabilidade econômica"}, {"c": "", "t": "7.8"}, {"c": "dou-paragraph", "t": "6.1.3.9 O OCP, após a auditoria e a avaliação, deve emitir relatório, registrando seu resultado, tendo como referência este RAC."}, {"c": "dou-paragraph", "t": "6.1.3.10 O relatório de auditoria e de avaliação deve ser assinado, pelo menos, pela equipe auditora, sendo que uma cópia deve ser disponibilizada ao Fabricante solicitante da certificação."}, {"c": "dou-paragraph", "t": "6.1.3.11 Qualquer alteração no processo produtivo deve ser informada ao OCP e acarreta, caso impacte na conformidade do produto ou serviço, em nova auditoria ou nova avaliação ou ambos."}, {"c": "dou-paragraph", "t": "6.1.3.12 No caso de certificação com base em protótipos, cabe ao OCP, durante a auditoria, assegurar que o produto produzido em escala corresponde ao protótipo ensaiado."}, {"c": "dou-paragraph", "t": "6.1.4 Plano de Ensaios Iniciais"}, {"c": "dou-paragraph", "t": "Quando ensaios forem previstos, os critérios para a definição do plano inicial de ensaios devem seguir os as condições definidas no RGCP. O plano de ensaios iniciais deve ser elaborado por família, modelo ou escopo de serviço e contemplar a amostragem especificada em cada Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.1.4.1 Definição dos Ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "A definição dos ensaios a serem realizados deve seguir conforme estabelecido no RGCP. Os ensaios são os definidos em cada no Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.1.4.2 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "A definição da amostragem e critérios de aceitação e rejeição devem seguir as condições gerais definidas no RGCP. Os critérios específicos estão descritos em cada Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.1.4.3 Definição do Laboratório"}, {"c": "dou-paragraph", "t": "Os critérios para a definição de laboratório devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.1.5 Tratamento de não conformidades na etapa de Avaliação Inicial"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de não conformidades na etapa de avaliação inicial devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.1.6 Emissão do Certificado de Conformidade"}, {"c": "dou-paragraph", "t": "6.1.6.1 Os critérios para emissão do Certificado de Conformidade devem seguir os requisitos estabelecidos no RGCP. O Certificado de Conformidade deve ter validade em anos, conforme estabelecido em cada Anexo Específico deste RAC, contados da data de emissão."}, {"c": "dou-paragraph", "t": "6.1.6.2 A forma de notação do modelo ou dos modelos que compõem a família, ou ainda, do escopo de serviço, deve ser conforme definido em cada Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.1.6.3 O OCP deve observar os critérios adicionais para a emissão do certificado estabelecidos em cada Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.2 Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "A avaliação de manutenção deve ser realizada pelo OCP de acordo com o RGCP (naquilo que for aplicável), o qual deve programar auditorias periódicas ou ensaios ou a combinação dos dois, conforme previsto em cada Anexo Específico, para constatar se as condições técnico-organizacionais que deram origem à concessão inicial da certificação continuam a ser cumpridas."}, {"c": "dou-paragraph", "t": "6.2.1 Auditoria de Manutenção do Sistema de Gestão da Ambiental e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "6.2.1.1 Os critérios para auditoria de manutenção devem seguir os requisitos estabelecidos no RGCP (no que for aplicável) e no subitem 6.1.3. A Auditoria de Manutenção deve ser realizada nos períodos estabelecidos em cada Anexo Específico deste RAC, contados da data de emissão do certificado."}, {"c": "dou-paragraph", "t": "6.2.1.2 Com base em evidências que as justifiquem, o OCP pode realizar outras auditorias extraordinárias no período de 12 (doze) meses."}, {"c": "dou-paragraph", "t": "6.2.1.3 Caso o Fabricante detentor da certificação apresente um Certificado do SGA, dentro de seu prazo de validade, o OCP pode, sob sua análise e responsabilidade, optar por não avaliar o SGA previsto nesse RAC durante a etapa de avaliação de manutenção. O Certificado deve ter sido emitido por um OAC acreditado pelo Inmetro ou membro do IAF ou da Global Accreditation Cooperation Incorporated, para o escopo de acreditação e segundo a edição vigente da norma ISO 14001 (e suas traduções) ou norma ABNT NBR ISO 14001. A certificação deve ser válida para o processo produtivo na unidade fabril do objeto a ser certificado. Nesse caso, o Fabricante deve colocar à disposição do OCP todos os documentos correspondentes a essa certificação e apresentar os registros do processo produtivo onde conste claramente a identificação do objeto da certificação. O OCP deve analisar a documentação pertinente para assegurar que os requisitos descritos na Tabela 1, do subitem 6.1.3.5 foram atendidos para o SGA."}, {"c": "dou-paragraph", "t": "6.2.1.4 É responsabilidade do Fabricante assegurar que o Sistema de Gestão Ambiental, certificado com base na edição vigente da norma ISO 14001 (e suas traduções) ou norma ABNT NBR ISO 14001, é executado e aplicado considerando a conformidade aos Requisitos de Avaliação da Conformidade específicos do objeto."}, {"c": "dou-paragraph", "t": "6.2.2 Plano de Ensaios de Manutenção"}, {"c": "dou-paragraph", "t": "Quando ensaios forem previstos, os critérios para o plano de ensaios de manutenção devem seguir o estabelecido no RGCP. Os ensaios devem ser realizados conforme a periodicidade estabelecida em cada Anexo Específico deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.1 Definição de ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "Os ensaios devem estar de acordo com os critérios estabelecidos no subitem 6.1.4.1 deste documento."}, {"c": "dou-paragraph", "t": "6.2.2.2 Definição da amostragem de manutenção"}, {"c": "dou-paragraph", "t": "Devem ser observados os critérios estabelecidos no subitem 6.1.4.2 deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.3 Definição do laboratório"}, {"c": "dou-paragraph", "t": "Devem ser observadas as disposições descritas no subitem 6.1.4.3 deste RAC."}, {"c": "dou-paragraph", "t": "6.2.3 Tratamento de não conformidades na etapa de Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de não conformidades na etapa de avaliação de manutenção devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.4 Confirmação da Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios de confirmação da manutenção devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.3 Avaliação de Recertificação"}, {"c": "dou-paragraph", "t": "Os critérios para avaliação de recertificação estão estabelecidos no RGCP. A Avaliação de Recertificação deve ser realizada com a periodicidade estabelecida em cada Anexo Específico deste RAC, devendo ser finalizada até a data de validade do Certificado de Conformidade anteriormente emitido."}, {"c": "dou-paragraph", "t": "7. TRATAMENTO DE RECLAMAÇÕES"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de reclamações devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "8. ATIVIDADES EXECUTADAS POR OCP ACREDITADO POR MEMBRO DO MLA DO IAF OU DA GLOBAL ACCREDITATION COOPERATION INCORPORATED"}, {"c": "dou-paragraph", "t": "Os critérios para atividades executadas por OCPs acreditados por membro do IAF ou da Global Accreditation Cooperation Incorporated devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "9. TRANSFERÊNCIA DA CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Os critérios para a transferência da certificação devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "10. ENCERRAMENTO DA CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Os critérios para encerramento de Certificação devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "11. SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "11.1 O Selo de Identificação da Conformidade tem por objetivo identificar que o objeto da certificação foi submetido ao processo de avaliação da conformidade e atende aos requisitos contidos neste RAC."}, {"c": "dou-paragraph", "t": "11.2 O modelo, as características, a rastreabilidade e as formas de aposição do Selo de Identificação da Conformidade devem seguir o estabelecido no Anexo II, complementadas pelas contidas em cada Anexo Específico."}, {"c": "dou-paragraph", "t": "11.3 O Selo de Identificação da Conformidade pode ser impresso no Certificado de Conformidade, marcado ou aposto ao produto ou impresso ou aposto à embalagem ou aposto em ambos, de acordo com o estabelecido em cada Anexo Específico."}, {"c": "dou-paragraph", "t": "12. AUTORIZAÇÃO PARA USO DO SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "Os critérios para Autorização do uso do Selo de Identificação da Conformidade devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "13. RESPONSABILIDADES E OBRIGAÇÕES"}, {"c": "dou-paragraph", "t": "Os critérios para responsabilidades e obrigações devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "14. ACOMPANHAMENTO NO MERCADO"}, {"c": "dou-paragraph", "t": "Os critérios para acompanhamento no mercado devem seguir as condições descritas no RGCP."}, {"c": "dou-paragraph", "t": "15. PENALIDADES"}, {"c": "dou-paragraph", "t": "Os critérios para aplicação de penalidades devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "16. DENÚNCIAS, RECLAMAÇÕES E SUGESTÕES"}, {"c": "dou-paragraph", "t": "Os critérios para denúncias, reclamações e sugestões devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "ANEXO ESPECÍFICO A"}, {"c": "dou-paragraph", "t": "SUSTENTABILIDADE DE POLÍMEROS DE ETENO DE FONTE RENOVÁVEL"}, {"c": "dou-paragraph", "t": "A.1. OBJETIVO E ESCOPO"}, {"c": "dou-paragraph", "t": "Este Anexo estabelece os requisitos específicos aplicáveis à certificação de polímeros de eteno de fonte renovável, produzidos pela indústria química e avaliados em conjunto com a cadeia de suprimento relevante para os atributos de sustentabilidade declarados. O Anexo aplica-se, em especial, a grânulos (pellets ou nurdles) cuja fração polimérica principal derive de eteno obtido a partir de matéria-prima renovável, observadas as limitações e recortes de escopo declarados no certificado."}, {"c": "dou-paragraph", "t": "A.1.1 Agrupamento para efeito de certificação"}, {"c": "dou-paragraph", "t": "Para efeitos da certificação de polímero de eteno de fonte renovável aplica-se o conceito de família. São considerados da mesma família os polímeros de eteno de fonte renovável de um determinado tipo, que sejam produzidos na mesma unidade fabril, pela mesma rota tecnológica principal e com controles equivalentes sobre conteúdo renovável e rastreabilidade."}, {"c": "dou-paragraph", "t": "Nota 1: Os tipos de polímeros de eteno de fonte renovável são: (a) Polietileno de alta densidade - PEAD, (b) Polietileno de baixa densidade - PEBD e (c) Polietileno linear de baixa densidade - PEBDL."}, {"c": "dou-paragraph", "t": "Nota 2: Alterações relevantes de matéria-prima, aditivos, processo, metodologia de quantificação podem exigir nova avaliação para efeitos de constituição de uma nova família."}, {"c": "dou-paragraph", "t": "A.2 DOCUMENTOS COMPLEMENTARES"}, {"c": "dou-paragraph", "t": "Para fins deste Anexo, são adotados os seguintes documentos complementares:"}, {"c": "", "t": "ABNT NBR 17283"}, {"c": "", "t": "Sustentabilidade de produtos químicos - Critérios ambientais, sociais e de governança - Polímeros de eteno de fonte renovável."}, {"c": "", "t": "ASTM D6866"}, {"c": "", "t": "Standard Test Methods for Determining the Biobased Content of Solid, Liquid, and Gaseous Samples Using Radiocarbon Analysis."}, {"c": "", "t": "ISO 16620-2"}, {"c": "", "t": "Plastics - Biobased content - Part 2: Determination of biobased carbon content."}, {"c": "", "t": "ISO 22095"}, {"c": "", "t": "Chain of custody - General terminology and models"}, {"c": "", "t": "ISO 22095-2"}, {"c": "", "t": "Chain of custody - Part 2: Requirements and guidelines for mass balance"}, {"c": "dou-paragraph", "t": "A.3 DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Para fins deste Anexo Específico são adotadas as definições a seguir, complementadas pelas contidas nos documentos complementares citados no item A.2."}, {"c": "dou-paragraph", "t": "A.3.1 Cadeia de custódia"}, {"c": "dou-paragraph", "t": "Conjunto de controles que assegura a transferência, o monitoramento e a integridade das informações e quantidades ao longo da cadeia de suprimento relevante."}, {"c": "dou-paragraph", "t": "A.3.2 Eteno de fonte renovável"}, {"c": "dou-paragraph", "t": "Olefina obtida a partir de matérias-primas renováveis, normalmente por conversão de insumos de origem biológica."}, {"c": "dou-paragraph", "t": "A.3.3 Polímero de eteno de fonte renovável"}, {"c": "dou-paragraph", "t": "Polímero obtido a partir de eteno de fonte renovável, total ou parcialmente, com conteúdo renovável demonstrado por método reconhecido."}, {"c": "dou-paragraph", "t": "A.3.4 Teor de carbono biogênico"}, {"c": "dou-paragraph", "t": "Fração de carbono de origem biológica presente no produto, determinada por método analítico aplicável."}, {"c": "dou-paragraph", "t": "A.4 ETAPAS DO PROCESSO DE AVALIAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "A certificação da sustentabilidade de polímero de eteno de fonte renovável deve se dar conforme o MEC descrito a seguir:"}, {"c": "dou-paragraph", "t": "Modelo Especial de Certificação - MEC: Avaliação Inicial consistindo de ensaios em amostras retiradas no fabricante, incluindo auditoria do Sistema de Gestão Ambiental (SGA) e avaliação do processo produtivo, seguida de Avaliação de Manutenção periódica através de coleta de amostra do produto na fábrica, para realização das atividades de avaliação da conformidade, e auditoria do SGA e avaliação do processo produtivo e Avaliação de Recertificação semelhante à Avaliação Inicial."}, {"c": "dou-paragraph", "t": "A.4.1 Modelo Especial de Certificação - MEC"}, {"c": "dou-paragraph", "t": "A.4.1.1 Avaliação Inicial"}, {"c": "dou-paragraph", "t": "A.4.1.1.1 Auditoria Inicial do Sistema de Gestão Ambiental e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "A.4.1.1.1.1 Os critérios de auditoria inicial do sistema de gestão e avaliação do processo produtivo devem seguir as condições descritas no RAC."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.2 Adicionalmente, O OCP deve verificar se o Fabricante cumpre integralmente a norma ABNT NBR 17283."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.3 O OCP deve verificar se o Fabricante mantém a classificação de documentos e evidências em categorias proporcionais ao risco e à materialidade dos requisitos, conforme Tabela A.1 a seguir:"}, {"c": "dou-paragraph", "t": "Tabela A.1: Categorias de documentos, sua natureza e evidência mínimas."}, {"c": "", "t": "Categoria"}, {"c": "", "t": "Natureza"}, {"c": "", "t": "Evidências mínimas"}, {"c": "", "t": "Legislação mínima"}, {"c": "", "t": "Obrigatória"}, {"c": "", "t": "CAR ativo quando aplicável; documentação fundiária regularizada; licenças ambientais aplicáveis; declarações legais exigidas."}, {"c": "", "t": "Operacional essencial"}, {"c": "", "t": "Obrigatória"}, {"c": "", "t": "Procedimento de amostragem; registros de rastreabilidade; controles de quantidade; relatórios de teor de carbono biogênico; inventários ou relatórios verificados de emissões."}, {"c": "", "t": "Garantia complementar"}, {"c": "", "t": "Voluntária/Auxiliar"}, {"c": "", "t": "Certificações reconhecidas, auditorias de segunda parte, bases de dados de sustentabilidade e relatórios adicionais."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.4 O OCP deve verificar se o fabricante conduz avaliação de risco contemplando, no mínimo, origem da matéria-prima, perfil do fornecedor, riscos socioambientais, complexidade logística, integridade dos dados, mudanças regulatórias e criticidade dos atributos declarados."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.5 O OCP deve averiguar se o fabricante revisa sua avaliação de risco e de controles associados quando ocorrem mudanças significativas de fornecedor, escopo, formulação, método de cálculo ou rota produtiva."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.6 Devem ser examinados os balanços de massa dos produtos, valendo-se inclusive de: Relatório de Rastreabilidade e Declaração de Conteúdo, Declarações de Sustentabilidade, Comprovantes de Pesagem, Conhecimentos de Embarque ou outra documentação aplicável."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.7 O OCP deve verificar se o balanço de massa foi realizado com base em sistema de cadeia de custódia documentado, auditável e rastreável, conforme os princípios da ISO 22095 e os requisitos da ISO 22095-2, contemplando, no mínimo, a identificação dos insumos elegíveis, produtos de saída, limites físicos e temporais do sistema, fatores de conversão, perdas, saldos, critérios de alocação, registros de entrada e saída, prevenção de dupla contagem e regras claras para comunicação de alegações ambientais associadas ao produto."}, {"c": "dou-paragraph", "t": "A.4.1.1.1.7.1 Dentre as formas possíveis de se evidenciar a consistência do balanço de massas e a cadeia de custódia do conteúdo renovável, de modo a verificar a integridade, a rastreabilidade e a não duplicidade das massas declaradas para certificação, o OCP pode, preferencialmente, verificar as informações registradas na plataforma da Agência Brasileira de Desenvolvimento Industrial (ABDI), Recircula Brasil (https://recirculabrasil.com.br/)."}, {"c": "dou-paragraph", "t": "A.4.1.1.2 Definição dos Ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "A.4.1.1.2.1 Devem ser realizados os ensaios, de acordo com a ISO 16620-2 ou a ASTM D6866, por família."}, {"c": "dou-paragraph", "t": "A.4.1.1.2.2 O OCP deve verificar se os polímeros de eteno de fonte renovável apresentam teor de carbono biogênico em relação ao carbono orgânico total conforme a Tabela A.2 a seguir:"}, {"c": "dou-paragraph", "t": "Tabela A.2 - Teor de carbono biogênico para os polímeros de eteno de fonte renovável"}, {"c": "dou-paragraph", "t": "A.4.1.1.3 Definição de Amostragem"}, {"c": "dou-paragraph", "t": "A.4.1.1.3.1 Devem ser coletadas amostras (prova, contraprova e testemunha) para realização dos ensaios previstos no subitem A.4.1.1.2 de 1 (um) modelo por família, devendo ser selecionado aquele que represente a configuração mais completa e mais desfavorável da família."}, {"c": "dou-paragraph", "t": "A.4.1.1.3.2 É responsabilidade do OCP, baseado nas normas aplicáveis estabelecidas no item A.2 deste Anexo e na análise dos diferentes tipos de variações/modelos permitidos dentro da família, definir o número de amostras a serem coletadas."}, {"c": "dou-paragraph", "t": "A.4.1.1.3.3 Se houver reprovação na amostra de prova, e esta reprovação interferir na constituição do produto como um todo, o OCP deve determinar se o produto deve ser submetido a todos os ensaios estabelecidos aplicáveis ao produto. Caso contrário, somente devem ser realizados os ensaios cujos resultados são afetados pela reprovação, ficando sob a responsabilidade do OCP tomar tal decisão."}, {"c": "dou-paragraph", "t": "A.4.1.1.4 Emissão do Certificado de Conformidade"}, {"c": "dou-paragraph", "t": "A.4.1.1.4.1 O Certificado de Conformidade deve ter validade de 5 (cinco) anos."}, {"c": "dou-paragraph", "t": "A.4.1.1.4.1.1 No Certificado de Conformidade, o(s) modelo(s) da família deve(m) ser notado(s) conforme Tabela A.3."}, {"c": "dou-paragraph", "t": "Tabela A.3 - Notação do(s) modelo(s) pertencente(s) à família no certificado de conformidade."}, {"c": "", "t": "Marca"}, {"c": "", "t": "Modelo (Designação Comercial do Modelo e Códigos de referência comercial, se existentes)"}, {"c": "", "t": "Descrição (Descrição Técnica do Modelo)- Teor de carbono biogênico relação ao carbono orgânico total; e- Outras características técnicas ou constitutivas que diferenciam os modelos da família."}, {"c": "", "t": "Código de barras comercial (quando existente) de todas as versões."}, {"c": "dou-paragraph", "t": "A.4.1.2 Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "A periodicidade da avaliação de manutenção é de 12 (doze) meses, contados da concessão do certificado."}, {"c": "dou-paragraph", "t": "A.4.1.2.1 Auditoria de Manutenção do Sistema de Gestão Ambiental e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "A auditoria do SGA e a avaliação do processo produtivo, realizada conforme o previsto no subitem A.4.1.1.1, deve ser realizada a cada 12 (doze) meses, contados da data de emissão do certificado."}, {"c": "dou-paragraph", "t": "A.4.1.2.2 Definição de ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "A.4.1.2.2.1 É responsabilidade do OCP, baseado na análise das variações permitidas dentro da família, definir os ensaios de cada norma aplicável ao produto, bem como o plano de ensaios de manutenção a serem realizados, nas respectivas amostras a serem coletadas."}, {"c": "dou-paragraph", "t": "A.4.1.2.2.2 Devem ser realizados os ensaios na 2ª e 4ª avaliações de manutenção, de acordo com a ISO 16620-2 ou a ASTM D6866, por família."}, {"c": "dou-paragraph", "t": "A.4.1.2.3 Definição de amostragem de manutenção"}, {"c": "dou-paragraph", "t": "A.4.1.2.3.1 Os critérios para definição de amostragem de manutenção devem seguir os requisitos estabelecidos no subitem A.4.1.1.3 deste Anexo Específico."}, {"c": "dou-paragraph", "t": "A.4.1.2.3.2 A amostra deve ser coletada, aleatoriamente, de cada família de produto certificado, na produção, considerando que deve ser possível realizar no produto selecionado todos os ensaios previstos."}, {"c": "dou-paragraph", "t": "A.5. SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "A.5.1 Os critérios gerais para o Selo de Identificação da Conformidade estão definidos no Anexo II."}, {"c": "dou-paragraph", "t": "A.5.2 O Selo de Identificação da Conformidade deve ser aposto na etiqueta da embalagem primária do produto."}, {"c": "dou-paragraph", "t": "ANEXO ESPECÍFICO B"}, {"c": "dou-paragraph", "t": "SUSTENTABILIDADE DE PRODUTOS MANUFATURADOS A PARTIR DE POLÍMEROS DE ETENO DE FONTE RENOVÁVEL"}, {"c": "dou-paragraph", "t": "B.1. OBJETIVO E ESCOPO"}, {"c": "dou-paragraph", "t": "Este Anexo estabelece os requisitos específicos aplicáveis à certificação de produtos manufaturados a partir de polímeros de eteno de fonte renovável, produzidos pela indústria química e avaliados em conjunto com a cadeia de suprimento relevante para os atributos de sustentabilidade declarados. O Anexo aplica-se aos produtos manufaturados apresentados na Tabela B.1 a seguir, onde estão associados os produtos manufaturados e sua Nomenclatura Comum Mercosul (NCM) correspondente."}, {"c": "dou-paragraph", "t": "Tabela B.1. Produtos manufaturados a partir de polímeros de eteno de fonte renovável e sua Nomenclatura Comum Mercosul (NCM)."}, {"c": "", "t": "CódigoNCM"}, {"c": "", "t": "Descrição da NCM"}, {"c": "", "t": "Exemplos de Produtos Manufaturados"}, {"c": "", "t": "3916"}, {"c": "", "t": "Monofilamentos cuja maior dimensão da seção transversal seja superior a 1 mm (monofios), varas, bastões e perfis, mesmo trabalhados à superfície, mas não trabalhados de outro modo, de plástico."}, {"c": "", "t": "-"}, {"c": "", "t": "39161000"}, {"c": "", "t": "- De polímeros de etileno"}, {"c": "", "t": "- Bastões,- Tarugos."}, {"c": "", "t": "3917"}, {"c": "", "t": "Tubos e seus acessórios (por exemplo, juntas, cotovelos, flanges, uniões), de plástico."}, {"c": "", "t": "-"}, {"c": "", "t": "39172"}, {"c": "", "t": "- Tubos rígidos:"}, {"c": "", "t": "-"}, {"c": "", "t": "39172100"}, {"c": "", "t": "-- De polímeros de etileno"}, {"c": "", "t": "- Composição em tubos de irrigação,- Mangueira atóxica leitosa."}, {"c": "", "t": "391732"}, {"c": "", "t": "-- Outros, não reforçados com outras matérias, nem associados de outra forma com outras matérias, sem acessórios"}, {"c": "", "t": "-"}, {"c": "", "t": "39173210"}, {"c": "", "t": "De copolímeros de etileno"}, {"c": "", "t": "- Conduítes,- Isolamento de fios e cabos XLPE de baixa e média tensão.- Tubos."}, {"c": "", "t": "3920"}, {"c": "", "t": "Outras chapas, folhas, películas, tiras e lâminas, de plástico não alveolar, não reforçadas nem estratificadas, sem suporte, nem associadas de forma semelhante a outras matérias."}, {"c": "", "t": "-"}, {"c": "", "t": "392010"}, {"c": "", "t": "- De polímeros de etileno"}, {"c": "", "t": "-"}, {"c": "", "t": "39201010"}, {"c": "", "t": "De densidade igual ou superior a 0,94, espessura inferior ou igual a 19 micrômetros (mícrons), em rolos de largura inferior ou igual a 66 cm"}, {"c": "", "t": "- Filmes agrícolas (proteção de estufas),- Filmes para fraldas,- Fita para isolamento (fita zebrada),- Liners (revestimentos para proteger, armazenar e transportar materiais diversos, especialmente no agronegócio e na indústria)."}, {"c": "", "t": "3920109"}, {"c": "", "t": "Outras"}, {"c": "", "t": "39201091"}, {"c": "", "t": "De densidade inferior a 0,94, com óleo de parafina e carga (sílica e negro de fumo), apresentando nervuras paralelas entre si, com uma resistência elétrica igual ou superior a 0,030 ohms.cm 2 , mas inferior ou igual a 0,120 ohms.cm 2 , em rolos, do tipo utilizado para a fabricação de separadores de acumuladores elétricos"}, {"c": "", "t": "- Manta de isolamento para baterias."}, {"c": "", "t": "39201099"}, {"c": "", "t": "Outras"}, {"c": "", "t": "- Filme stretch,- Lona plástica,- Não-tecido bicomponente e fibras em geral (Tipo TNT),- Placa em polietileno,- Placas e solados espumados e reticulados (entressola unisole) para calçados, brinquedos, artigos esportivos."}, {"c": "", "t": "3921"}, {"c": "", "t": "Outras chapas, folhas, películas, tiras e lâminas, de plástico."}, {"c": "", "t": "-"}, {"c": "", "t": "392190"}, {"c": "", "t": "- Outras"}, {"c": "", "t": "-"}, {"c": "", "t": "3921901"}, {"c": "", "t": "Estratificadas, reforçadas ou com suporte"}, {"c": "", "t": "-"}, {"c": "", "t": "39219012"}, {"c": "", "t": "De polietileno, com reforço de napas de fibras de polietileno paralelizadas, superpostas entre si em ângulo de 90º e impregnadas com resinas"}, {"c": "", "t": "- Laminado balístico."}, {"c": "", "t": "3922"}, {"c": "", "t": "Banheiras, boxes para chuveiros (polibãs*), pias, lavatórios, bidés, sanitários e seus assentos e tampas, caixas de descarga (autoclismos*) e artigos semelhantes para usos sanitários ou higiênicos, de plástico."}, {"c": "", "t": "-"}, {"c": "", "t": "39221000"}, {"c": "", "t": "- Banheiras, boxes para chuveiros (polibãs*), pias e lavatórios"}, {"c": "", "t": "-"}, {"c": "", "t": "39222000"}, {"c": "", "t": "- Assentos e tampas, de sanitários"}, {"c": "", "t": "- Assentos de vaso sanitário"}, {"c": "", "t": "39229000"}, {"c": "", "t": "- Outros"}, {"c": "", "t": "- Caixa descarga plástica branca,- Conjunto obturador caixa descarga,- Dispenser para sabão,- Lixeira plástica."}, {"c": "", "t": "3923"}, {"c": "", "t": "Artigos de transporte ou de embalagem, de plástico; rolhas, tampas, cápsulas e outros dispositivos para fechar recipientes, de plástico."}, {"c": "", "t": "-"}, {"c": "", "t": "392310"}, {"c": "", "t": "- Caixas, caixotes, engradados e artigos semelhantes"}, {"c": "", "t": "-"}, {"c": "", "t": "39231090"}, {"c": "", "t": "Outros"}, {"c": "", "t": "- Cabo plástico,- Caixa plástica organizadora,- Cesta plástica,- Embalagem cartonada para alimentos e bebidas (tipo Tetra Pak e Sig),"}, {"c": "", "t": "- Embalagens para cosméticos,- Embalagens para produtos alimentícios,- Engradados para peixes e vegetais,- Engradados para transporte de garrafas de bebidas,- Filmes stretch (para paletização de produtos),- Filmes termoecolhíveis para paletização,"}, {"c": "", "t": "- Raschel (embalagens para frutas e legumes), redes e cordas de proteção e sombreamento,- Tubos para embalagens de alimentos e cosméticos, frascos flexíveis para produtos sólidos, líquidos ou pastosos para higiene, limpeza."}, {"c": "", "t": "39232"}, {"c": "", "t": "- Sacos de quaisquer dimensões, bolsas e cartuchos:"}, {"c": "", "t": "-"}, {"c": "", "t": "392321"}, {"c": "", "t": "-- De polímeros de etileno"}, {"c": "", "t": "-"}, {"c": "", "t": "39232110"}, {"c": "", "t": "De capacidade inferior ou igual a 1.000 cm 3"}, {"c": "", "t": "- Ensacamento de frutos no pé,- Sacarias industriais, embalagem automática de produtos sólidos (embalagens para grãos diversos),- Sacolas para varejo, sacolas promocionais, sacolas para produtos e embalagens para alimentos congelados,"}, {"c": "", "t": "- Sacos industriais,- Sacos para autoclave,- Sacos plásticos,"}, {"c": "", "t": "392330"}, {"c": "", "t": "- Garrafões, garrafas, frascos e artigos semelhantes"}, {"c": "", "t": "- Garrafas e frascos para alimentos e bebidas, garrafas para produtos lácteos,- Garrafas para produtos de higiene e limpeza, garrafas para álcool etílico, frascos para detergente concentrado,- Recipientes rígidos para óleos lubrificantes,- Tanques para limpador de para-brisas e dutos de ar de automóveis."}, {"c": "", "t": "39234000"}, {"c": "", "t": "- Bobinas, carretéis, canelas e suportes semelhantes"}, {"c": "", "t": "- Bobina de saco plástico picotada."}, {"c": "", "t": "39235000"}, {"c": "", "t": "- Rolhas, tampas, cápsulas e outros dispositivos para fechar recipientes"}, {"c": "", "t": "- Lacres plásticos,- Tampas de reservatório,- Tampas gerais, tampas de rosca, tampas para garrafas de bebidas."}, {"c": "", "t": "39239010"}, {"c": "", "t": "Paletes simples, paletes-caixas e outros estrados para carga; taipais de paletes"}, {"c": "", "t": "- Fivela plástica para fita de arquear.- Palete plástico."}, {"c": "", "t": "3924"}, {"c": "", "t": "Serviços de mesa, artigos de cozinha, outros artigos de uso doméstico e artigos de higiene ou de toucador, de plástico."}, {"c": "", "t": "-"}, {"c": "", "t": "39241000"}, {"c": "", "t": "Serviços de mesa e outros utensílios de mesa ou de cozinha"}, {"c": "", "t": "- Copo descartável,- Embalagem descartável multiuso."}, {"c": "", "t": "3925"}, {"c": "", "t": "Artigos para apetrechamento de construções, de plástico, não especificados nem compreendidos noutras posições."}, {"c": "", "t": "-"}, {"c": "", "t": "39251000"}, {"c": "", "t": "- Reservatórios, cisternas, cubas e recipientes análogos, de capacidade superior a 300 l"}, {"c": "", "t": "- Bombonas para produtos químicos,- Caixa d'água,- Reservatório plástico,- Tanque plástico."}, {"c": "", "t": "392590"}, {"c": "", "t": "- Outros"}, {"c": "", "t": "-"}, {"c": "", "t": "3926"}, {"c": "", "t": "Outras obras de plástico e obras de outras matérias das posições 39.01 a 39.14."}, {"c": "", "t": "-"}, {"c": "", "t": "39261000"}, {"c": "", "t": "- Artigos de escritório e artigos escolares"}, {"c": "", "t": "- Caixas para correspondência e usos diversos,- Chaveiro,- Display para documentos."}, {"c": "", "t": "39262000"}, {"c": "", "t": "- Vestuário e seus acessórios (incluindo as luvas, mitenes e semelhantes)"}, {"c": "", "t": "- Avental,- Capa protetora,- Protetor de braço estéril."}, {"c": "", "t": "39263000"}, {"c": "", "t": "- Guarnições para móveis, carroçarias ou semelhantes"}, {"c": "", "t": "- Clipes e materiais de fixação"}, {"c": "", "t": "39264000"}, {"c": "", "t": "- Estatuetas e outros objetos de ornamentação"}, {"c": "", "t": "- Miniaturas,- Peças decorativas."}, {"c": "", "t": "392690"}, {"c": "", "t": "- Outras"}, {"c": "", "t": "-"}, {"c": "", "t": "39269010"}, {"c": "", "t": "Arruelas (anilhas)"}, {"c": "", "t": "- Anéis,- Vedações."}, {"c": "", "t": "3926902"}, {"c": "", "t": "Correias de transmissão e correias transportadoras"}, {"c": "", "t": "-"}, {"c": "", "t": "39269022"}, {"c": "", "t": "Transportadoras"}, {"c": "", "t": "- Correias transportadoras de plásticos."}, {"c": "", "t": "39269030"}, {"c": "", "t": "Bolsas para uso em medicina (hemodiálise e usos semelhantes)"}, {"c": "", "t": "- Bolsas de fluídos,- Frasco e bolsas para administração de nutrição enteral."}, {"c": "", "t": "39269040"}, {"c": "", "t": "Artigos de laboratório ou de farmácia"}, {"c": "", "t": "- Frasco estéril para coleta de fezes ou urina,- Microplaca fundo chato,- Microtubo,- Ponteira sem filtro,- Tubo de reação."}, {"c": "", "t": "39269050"}, {"c": "", "t": "Acessórios do tipo utilizado em linhas de sangue para hemodiálise, tais como: obturadores, incluindo os reguláveis (clamps), clipes e semelhantes"}, {"c": "", "t": "- Clamp umbilical,- Clamp deslizante,- Pinça rolete."}, {"c": "dou-paragraph", "t": "Nota: A listagem de produtos manufaturados não é exaustiva, portanto, o escopo deste Anexo abrange todos os produtos que podem ser relacionados às NCMs destacadas da Tabela B.1."}, {"c": "dou-paragraph", "t": "B.1.1 Agrupamento para efeito de certificação"}, {"c": "dou-paragraph", "t": "Para efeitos da certificação de produtos manufaturados a partir de polímero de eteno de fonte renovável aplica-se o conceito de família. São considerados da mesma família os produtos manufaturados a partir de um determinado tipo de polímeros de eteno de fonte renovável, que sejam produzidos na mesma unidade fabril, pela mesma rota tecnológica principal e com controles equivalentes sobre conteúdo renovável e rastreabilidade."}, {"c": "dou-paragraph", "t": "Nota 1: Os tipos de polímeros de eteno de fonte renovável são: (a) Polietileno de alta densidade - PEAD, (b) Polietileno de baixa densidade - PEBD e (c) Polietileno linear de baixa densidade - PEBDL."}, {"c": "dou-paragraph", "t": "Nota 2: Produtos manufaturados de graus de pureza distintos podem compor a mesma família quando as diferenças de formulação não afetarem o atendimento aos critérios declarados de conteúdo renovável, pegada de carbono e cadeia de custódia."}, {"c": "dou-paragraph", "t": "Nota 3: Alterações relevantes de matéria-prima, aditivos, processo, metodologia de quantificação podem exigir nova avaliação para efeitos de constituição de uma nova família."}, {"c": "dou-paragraph", "t": "Nota 4: Apenas um tipo de produto manufaturado pode compor uma família."}, {"c": "dou-paragraph", "t": "B.2. DOCUMENTOS COMPLEMENTARES"}, {"c": "dou-paragraph", "t": "Para fins deste Anexo, são adotados os documentos complementares a seguir:"}, {"c": "", "t": "ABNT NBR 17283"}, {"c": "", "t": "Sustentabilidade de produtos químicos - Critérios ambientais, sociais e de governança - Polímeros de eteno de fonte renovável."}, {"c": "", "t": "ASTM D6866"}, {"c": "", "t": "Standard Test Methods for Determining the Biobased Content of Solid, Liquid, and Gaseous Samples Using Radiocarbon Analysis."}, {"c": "", "t": "ISO 16620-2"}, {"c": "", "t": "Plastics - Biobased content - Part 2: Determination of biobased carbon content."}, {"c": "", "t": "ISO 22095"}, {"c": "", "t": "Chain of custody - General terminology and models"}, {"c": "", "t": "ISO 22095-2"}, {"c": "", "t": "Chain of custody - Part 2: Requirements and guidelines for mass balance"}, {"c": "dou-paragraph", "t": "B.3. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Para fins deste Anexo Específico são adotadas as definições a seguir, complementadas pelas contidas nos documentos complementares citados no item B.2."}, {"c": "dou-paragraph", "t": "B.3.1 Cadeia de custódia"}, {"c": "dou-paragraph", "t": "Conjunto de controles que assegura a transferência, o monitoramento e a integridade das informações e quantidades ao longo da cadeia de suprimento relevante."}, {"c": "dou-paragraph", "t": "B.3.2 Eteno de fonte renovável"}, {"c": "dou-paragraph", "t": "Olefina obtida a partir de matérias-primas renováveis, normalmente por conversão de insumos de origem biológica."}, {"c": "dou-paragraph", "t": "B.3.3 Polímero de eteno de fonte renovável"}, {"c": "dou-paragraph", "t": "Polímero obtido a partir de eteno de fonte renovável, total ou parcialmente, com conteúdo renovável demonstrado por método reconhecido."}, {"c": "dou-paragraph", "t": "B.3.4 Produto manufaturado"}, {"c": "dou-paragraph", "t": "Produto final manufaturado tendo como matéria-prima polímeros de eteno de fonte renovável."}, {"c": "dou-paragraph", "t": "B.3.5 Teor de carbono biogênico"}, {"c": "dou-paragraph", "t": "Fração de carbono de origem biológica presente no produto, determinada por método analítico aplicável."}, {"c": "dou-paragraph", "t": "B.4. ETAPAS DO PROCESSO DE AVALIAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "A certificação da sustentabilidade de produtos manufaturados a partir de polímero de eteno de fonte renovável deve se dar conforme o MEC descrito a seguir:"}, {"c": "dou-paragraph", "t": "Modelo Especial de Certificação - MEC: Avaliação Inicial consistindo de ensaios em amostras retiradas no fabricante, incluindo auditoria do Sistema de Gestão Ambiental (SGA) e avaliação do processo produtivo, seguida de Avaliação de Manutenção periódica através de coleta de amostra do produto na fábrica ou no comércio, para realização das atividades de avaliação da conformidade, e auditoria do SGA e avaliação do processo produtivo e Avaliação de Recertificação semelhante à Avaliação Inicial."}, {"c": "dou-paragraph", "t": "B.4.1 Modelo Especial de Certificação - MEC"}, {"c": "dou-paragraph", "t": "B.4.1.1 Avaliação Inicial"}, {"c": "dou-paragraph", "t": "B.4.1.1.1 Auditoria Inicial do Sistema de Gestão Ambiental e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "B.4.1.1.1.1 Os critérios de auditoria inicial do sistema de gestão e avaliação do processo produtivo devem seguir as condições descritas no RAC."}, {"c": "dou-paragraph", "t": "B.4.1.1.1.2 Adicionalmente, o OCP deve verificar se o Fabricante cumpre os seguintes requisitos estabelecidos na norma ABNT NBR 17283, conforme definidos na Tabela B.2 a seguir."}, {"c": "dou-paragraph", "t": "Tabela B.2: Requisitos mínimos de Avaliação do Processo Produtivo para fabricantes de produtos manufaturados a partir de polímeros de eteno de fonte renovável com base na norma ABNT NBR 17283."}, {"c": "", "t": "Requisitos de Avaliação do Processo Produtivo"}, {"c": "", "t": "Itens da norma ABNT NBR 17283"}, {"c": "", "t": "Sistema de gestão da organização"}, {"c": "", "t": "4.1"}, {"c": "", "t": "Verificação e conformidade"}, {"c": "", "t": "4.2.1; 4.2.2; 4.2.3"}, {"c": "", "t": "Qualificação e treinamento de pessoal da organização"}, {"c": "", "t": "4.3"}, {"c": "", "t": "Auditorias internas"}, {"c": "", "t": "4.4"}, {"c": "", "t": "Registros e documentação"}, {"c": "", "t": "4.5"}, {"c": "", "t": "Disponibilidade para auditorias internas e externas"}, {"c": "", "t": "4.6"}, {"c": "", "t": "Integração com outros esquemas de certificação"}, {"c": "", "t": "4.7"}, {"c": "", "t": "Avaliação de risco"}, {"c": "", "t": "4.9"}, {"c": "", "t": "Frequência de atualização e verificação"}, {"c": "", "t": "4.10"}, {"c": "", "t": "Disposições complementares"}, {"c": "", "t": "4.11"}, {"c": "", "t": "Cadeia de produção responsável"}, {"c": "", "t": "4.12"}, {"c": "", "t": "Rastreabilidade"}, {"c": "", "t": "4.14.1; 4.14.3; 4.14.4"}, {"c": "", "t": "Gestão de recursos hídricos"}, {"c": "", "t": "4.16.1"}, {"c": "", "t": "Gestão de emissões"}, {"c": "", "t": "4.16.5"}, {"c": "", "t": "Condições de trabalho"}, {"c": "", "t": "4.17.1.1; 4.17.1.2 (exceto a necessidade de evidências nas usinas fornecedoras de matérias-primas de fonte renovável); 4.17.2"}, {"c": "", "t": "Saúde e segurança"}, {"c": "", "t": "4.17.3 (exceto a necessidade de evidências em seus fornecedores de matéria-prima de fonte renovável)"}, {"c": "", "t": "Gestão de fornecedores"}, {"c": "", "t": "4.18"}, {"c": "", "t": "Avaliação da origem renovável do produto - Determinação do teor de carbono biogênico"}, {"c": "", "t": "5.1 (a determinação do teor de carbono biogênico deve ser aplicada aos produtos manufaturados a partir de polímeros de eteno de fonte renovável); 5.2; 5.3; 5.4"}, {"c": "dou-paragraph", "t": "B.4.1.1.1.3 O OCP deve verificar se o fabricante mantém a classificação de documentos e evidências em categorias proporcionais ao risco e à materialidade dos requisitos, conforme Tabela B.3 a seguir:"}, {"c": "dou-paragraph", "t": "Tabela B.3: Categorias de documentos, sua natureza e evidência mínimas."}, {"c": "", "t": "Categoria"}, {"c": "", "t": "Natureza"}, {"c": "", "t": "Evidências mínimas"}, {"c": "", "t": "Legislação mínima"}, {"c": "", "t": "Obrigatória"}, {"c": "", "t": "CAR ativo quando aplicável; documentação fundiária regularizada; licenças ambientais aplicáveis; declarações legais exigidas."}, {"c": "", "t": "Operacional essencial"}, {"c": "", "t": "Obrigatória"}, {"c": "", "t": "Procedimento de amostragem; registros de rastreabilidade; controles de quantidade; relatórios de teor de carbono biogênico; inventários ou relatórios verificados de emissões."}, {"c": "", "t": "Garantia complementar"}, {"c": "", "t": "Voluntária/auxiliar"}, {"c": "", "t": "Certificações reconhecidas, auditorias de segunda parte, bases de dados de sustentabilidade e relatórios adicionais."}, {"c": "dou-paragraph", "t": "B.4.1.1.1.4 O OCP deve verificar se o Fabricante conduz avaliação de risco contemplando, no mínimo, origem da matéria-prima, perfil do fornecedor, riscos socioambientais, complexidade logística, integridade dos dados, mudanças regulatórias e criticidade dos atributos declarados."}, {"c": "dou-paragraph", "t": "B.4.1.1.1.5 O OCP deve averiguar se o fabricante revisa sua avaliação de risco e de controles associados quando ocorrem mudanças significativas de fornecedor, escopo, formulação, método de cálculo ou rota produtiva."}, {"c": "dou-paragraph", "t": "B.4.1.1.1.6 Devem ser examinados os balanços de massa dos produtos, valendo-se inclusive de: Relatório de Rastreabilidade e Declaração de Conteúdo, Declarações de Sustentabilidade, Comprovantes de Pesagem, Conhecimentos de Embarque ou outra documentação aplicável."}, {"c": "dou-paragraph", "t": "B.4.1.1.1.7 O OCP deve verificar se o balanço de massa foi realizado com base em sistema de cadeia de custódia documentado, auditável e rastreável, conforme os princípios da ISO 22095 e os requisitos da ISO 22095-2, contemplando, no mínimo, a identificação dos insumos elegíveis, produtos de saída, limites físicos e temporais do sistema, fatores de conversão, perdas, saldos, critérios de alocação, registros de entrada e saída, prevenção de dupla contagem e regras claras para comunicação de alegações ambientais associadas ao produto."}, {"c": "dou-paragraph", "t": "B.4.1.1.1.7.1 Dentre as formas possíveis de se evidenciar a consistência do balanço de massas e a cadeia de custódia do conteúdo renovável, de modo a verificar a integridade, a rastreabilidade e a não duplicidade das massas declaradas para certificação, o OCP pode, preferencialmente, verificar as informações registradas na plataforma da Agência Brasileira de Desenvolvimento Industrial (ABDI), Recircula Brasil (https://recirculabrasil.com.br/)."}, {"c": "dou-paragraph", "t": "B.4.1.1.2 Definição dos Ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "B.4.1.1.2.1 Devem ser realizados os ensaios, de acordo com a ISO 16620-2 ou a ASTM D6866, por família."}, {"c": "dou-paragraph", "t": "B.4.1.1.2.2 O OCP deve verificar se os produtos manufaturados a partir de polímeros de eteno de fonte renovável apresentam teor de carbono biogênico em relação ao carbono orgânico total conforme a Tabela B.4 a seguir:"}, {"c": "dou-paragraph", "t": "Tabela B.4 - Teor de carbono biogênico para os produtos manufaturados a partir de polímeros de eteno de fonte renovável."}, {"c": "", "t": "CódigoNCM"}, {"c": "", "t": "Exemplos de Produtos Manufaturados"}, {"c": "", "t": "Teor mínimo de carbono biogênico em relação ao carbono total (%)(Válido a partir de dezembro/2026)"}, {"c": "", "t": "Teor mínimo de carbono biogênico em relação ao carbono total (%)(Válido a partir de dezembro/2030)"}, {"c": "", "t": "39161000"}, {"c": "", "t": "- Bastões,- Tarugos."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39172100"}, {"c": "", "t": "- Composição em tubos de irrigação,- Mangueira atóxica leitosa."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39173210"}, {"c": "", "t": "- Conduítes,- Isolamento de fios e cabos XLPE de baixa e média tensão,- Tubos."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39201010"}, {"c": "", "t": "- Filmes agrícolas (proteção de estufas),- Filmes para fraldas,- Fita para isolamento (fita zebrada),- Liners (revestimentos para proteger, armazenar e transportar materiais diversos, especialmente no agronegócio e na indústria)."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39201091"}, {"c": "", "t": "- Manta de isolamento para baterias."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39201099"}, {"c": "", "t": "- Filme stretch,- Lona plástica,- Não-tecido bicomponente e fibras em geral (Tipo TNT),- Placa em polietileno,- Placas e solados espumados e reticulados (entressola unisole) para calçados, brinquedos, artigos esportivos."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39219012"}, {"c": "", "t": "- Laminado balístico"}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39222000"}, {"c": "", "t": "- Assentos de vaso sanitário"}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39229000"}, {"c": "", "t": "- Caixa descarga plástica branca,- Conjunto obturador caixa descarga,- Dispenser para sabão,- Lixeira plástica."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39231090"}, {"c": "", "t": "- Cabo plástico,- Caixa plástica organizadora,- Cesta plástica,- Embalagem cartonada para alimentos e bebidas (tipo Tetra Pak e Sig),- Embalagens para cosméticos,"}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "- Embalagens para produtos alimentícios,- Engradados para peixes e vegetais,- Engradados para transporte de garrafas de bebidas,- Filmes stretch (para paletização de produtos),- Filmes termoecolhíveis para paletização,"}, {"c": "", "t": "- Raschel (embalagens para frutas e legumes), redes e cordas de proteção e sombreamento,- Tubos para embalagens de alimentos e cosméticos, frascos flexíveis para produtos sólidos, líquidos ou pastosos para higiene, limpeza."}, {"c": "", "t": "39232110"}, {"c": "", "t": "- Ensacamento de frutos no pé,- Sacarias industriais, embalagem automática de produtos sólidos (embalagens para grãos diversos),- Sacolas para varejo, sacolas promocionais, sacolas para produtos e embalagens para alimentos congelados,- Sacos industriais,- Sacos para autoclave,- Sacos plásticos."}, {"c": "", "t": "30"}, {"c": "", "t": "40"}, {"c": "", "t": "392330"}, {"c": "", "t": "- Garrafas e frascos para alimentos e bebidas, garrafas para produtos lácteos,- Garrafas para produtos de higiene e limpeza, garrafas para álcool etílico, frascos para detergente concentrado,- Recipientes rígidos para óleos lubrificantes,- Tanques para limpador de para-brisas e dutos de ar de automóveis."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39234000"}, {"c": "", "t": "- Bobina de saco plástico picotada."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39235000"}, {"c": "", "t": "- Lacres plásticos,- Tampas de reservatório,- Tampas gerais, tampas de rosca, tampas para garrafas de bebidas."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39239010"}, {"c": "", "t": "- Fivela plástica para fita de arquear.- Palete plástico."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39241000"}, {"c": "", "t": "- Bombonas para produtos químicos,- Copo descartável,- Embalagem descartável multiuso."}, {"c": "", "t": "30"}, {"c": "", "t": "40"}, {"c": "", "t": "39251000"}, {"c": "", "t": "- Caixa d'água,- Reservatório plástico,- Tanque plástico."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39261000"}, {"c": "", "t": "- Caixas para correspondência e usos diversos,- Chaveiro,- Display para documentos."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39262000"}, {"c": "", "t": "- Avental,- Capa protetora,- Protetor de braço estéril."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39263000"}, {"c": "", "t": "- Clipes e materiais de fixação"}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39264000"}, {"c": "", "t": "- Miniaturas,- Peças decorativas."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39269010"}, {"c": "", "t": "- Anéis,- Vedações."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39269022"}, {"c": "", "t": "- Correias transportadoras de plásticos."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39269030"}, {"c": "", "t": "- Bolsas de fluídos,- Frasco e bolsas para administração de nutrição enteral."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39269040"}, {"c": "", "t": "- Frasco estéril para coleta de fezes ou urina,- Microplaca fundo chato,- Microtubo,- Ponteira sem filtro,- Tubo de reação."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "", "t": "39269050"}, {"c": "", "t": "- Clamp umbilical,- Clamp deslizante,- Pinça rolete."}, {"c": "", "t": "20"}, {"c": "", "t": "30"}, {"c": "dou-paragraph", "t": "Nota: A listagem de produtos manufaturados não é exaustiva, portanto, o teor mínimo de carbono biogênico abrange a todos os produtos que podem ser relacionados às NCMs relacionadas na Tabela B.4."}, {"c": "dou-paragraph", "t": "B.4.1.1.3 Definição de Amostragem"}, {"c": "dou-paragraph", "t": "B.4.1.1.3.1 Devem ser coletadas amostras (prova, contraprova e testemunha) para realização dos ensaios previstos no subitem B.4.1.1.2 de 1 (um) modelo por família, devendo ser selecionado aquele que represente a configuração mais completa e mais desfavorável da família."}, {"c": "dou-paragraph", "t": "B.4.1.1.3.2 É responsabilidade do OCP, baseado nas normas aplicáveis estabelecidas no item B.2 deste Anexo e na análise dos diferentes tipos de variações/modelos permitidos dentro da família, definir o número de amostras a serem coletadas."}, {"c": "dou-paragraph", "t": "B.4.1.1.3.3 Se houver reprovação na amostra de prova, e esta reprovação interferir na constituição do produto como um todo, o OCP deve determinar se o produto deve ser submetido a todos os ensaios estabelecidos aplicáveis ao produto. Caso contrário, somente devem ser realizados os ensaios cujos resultados são afetados pela reprovação, ficando sob a responsabilidade do OCP tomar tal decisão."}, {"c": "dou-paragraph", "t": "B.4.1.1.4 Definição do Laboratório"}, {"c": "dou-paragraph", "t": "B.4.1.1.4.1 Os critérios para a definição de laboratório devem seguir os requisitos estabelecidos no RGCP, exceto pelo que se segue."}, {"c": "dou-paragraph", "t": "B.4.1.1.4.2 Enquanto não houver laboratório de 3ª parte, nacional, acreditado, podem ser utilizados laboratórios de 3ª parte, nacionais, não acreditados, desconsiderando-se a ordem de prioridade estabelecida no subitem 6.2.4.3.1 do RGCP."}, {"c": "dou-paragraph", "t": "Nota: Nessa situação, o OCP deve observar, em especial, o disposto no subitem 6.2.4.3.6 do RGCP."}, {"c": "dou-paragraph", "t": "B.4.1.1.5 Emissão do Certificado de Conformidade"}, {"c": "dou-paragraph", "t": "B.4.1.1.5.1 O Certificado de Conformidade deve ter validade de 5 (cinco) anos."}, {"c": "dou-paragraph", "t": "B.4.1.1.5.1.1 No Certificado de Conformidade, o(s) modelo(s) da família deve(m) ser notado(s) conforme Tabela 3."}, {"c": "dou-paragraph", "t": "Tabela 3 - Notação do(s) modelo(s) pertencente(s) à família no certificado de conformidade"}, {"c": "", "t": "Marca"}, {"c": "", "t": "Modelo (Designação Comercial do Modelo e Códigos de referência comercial, se existentes)"}, {"c": "", "t": "Descrição (Descrição Técnica do Modelo)- Teor de carbono biogênico relação ao carbono orgânico total; e- Outras características técnicas ou constitutivas que diferenciam os modelos da família."}, {"c": "", "t": "Código de barras comercial (quando existente) de todas as versões."}, {"c": "dou-paragraph", "t": "B.4.1.2 Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "A periodicidade da avaliação de manutenção é de 12 (doze) meses, contados da concessão do certificado."}, {"c": "dou-paragraph", "t": "B.4.1.2.1 Auditoria de Manutenção do Sistema de Gestão da Qualidade e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "A auditoria do SGA e a avaliação do processo produtivo, realizada conforme o previsto no subitem B.4.1.1.2, deve ser realizada a cada 12 (doze) meses, contados da data de emissão do certificado."}, {"c": "dou-paragraph", "t": "B.4.1.2.2 Definição de ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "B.4.1.2.2.1 É responsabilidade do OCP, baseado na análise das variações permitidas dentro da família, definir os ensaios de cada norma aplicável ao produto, bem como o plano de ensaios de manutenção a serem realizados, nas respectivas amostras a serem coletadas."}, {"c": "dou-paragraph", "t": "B.4.1.2.2.2 Devem ser realizados os ensaios na 2ª e 4ª avaliações de manutenção, de acordo com a ISO 16620-2 ou a ASTM D6866, por família."}, {"c": "dou-paragraph", "t": "B.4.1.2.3 Definição de amostragem de manutenção"}, {"c": "dou-paragraph", "t": "B.4.1.2.3.1 Os critérios para definição de amostragem de manutenção devem seguir os requisitos estabelecidos no subitem B.4.1.1.3 deste Anexo Específico e pelo que se segue."}, {"c": "dou-paragraph", "t": "B.4.1.2.3.2 A amostra deve ser coletada, aleatoriamente, de cada família de produto certificado, na produção, centro de distribuição ou no comércio, alternadamente, considerando que deve ser possível realizar no produto selecionado todos os ensaios previstos."}, {"c": "dou-paragraph", "t": "B.4.1.2.4 Definição do Laboratório"}, {"c": "dou-paragraph", "t": "B.4.1.2.4.1 Os critérios para a definição de laboratório devem seguir os requisitos estabelecidos no subitem B.4.1.1.4."}, {"c": "dou-paragraph", "t": "B.5 SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "B.5.1 Os critérios gerais para o Selo de Identificação da Conformidade estão definidos no Anexo II."}, {"c": "dou-paragraph", "t": "B.5.2 O Selo de Identificação da Conformidade deve ser aposto na embalagem primária do produto ou em uma etiqueta afixada ao produto ou marcado no produto."}, {"c": "dou-paragraph", "t": "ANEXO II"}, {"c": "dou-paragraph", "t": "SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "1. SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "O Selo de Identificação da Conformidade é o Selo Verde Brasil, cuja identidade visual segue o modelo estabelecido em ato do Ministro de Estado do Desenvolvimento, Indústria, Comércio e Serviços, conforme o Decreto nº 12.063, de 17 de junho de 2024."}, {"c": "dou-paragraph", "t": "1.1 Aposição do Selo"}, {"c": "dou-paragraph", "t": "O Selo Verde Brasil pode ser impresso no Certificado de Conformidade, marcado ou aposto ao produto ou impresso ou aposto à embalagem ou aposto em ambos, de acordo com estabelecido em cada Anexo Específico e conforme os subitens a seguir, devendo o mesmo ser legível e indelével."}, {"c": "dou-paragraph", "t": "1.2 Dimensões do Selo"}, {"c": "dou-paragraph", "t": "As dimensões mínimas do Selo Verde Brasil devem ser aquelas colocadas na Figura 1."}, {"c": "dou-paragraph", "t": "1.3 Área de Proteção do Selo"}, {"c": "dou-paragraph", "t": "A área de proteção assegura o espaçamento necessário ao redor do logo, garantindo o destaque e a clareza do Selo. Uma área de proteção de, no mínimo, X em todo o entorno do selo, utilizando a largura do ícone do centro (X) como unidade de referência."}, {"c": "dou-paragraph", "t": "1.4 Estratégias de Aplicação do Selo"}, {"c": "dou-paragraph", "t": "A aplicação do Selo Verde Brasil deve ocorrer sobre fundos da paleta primária ou em fotografias, priorizando áreas limpas e com pouca poluição visual para preservar a clareza e a visibilidade de seus elementos essenciais. Além disso, deve-se respeitar a proporção de contraste mínimo com a cor de fundo, conforme as normas de acessibilidade visual, garantindo a legibilidade adequada tanto dos componentes gráficos quanto dos textos associados, de acordo a figura 3."}, {"c": "dou-paragraph", "t": "1.5 Paleta de Cores do Selo"}, {"c": "dou-paragraph", "t": "A paleta de cores é um componente fundamental do sistema visual e parte essencial do Selo Verde Brasil. A figura 4 reúne as especificações técnicas e os valores de cada cor para correta aplicação do Selo em materiais impressos e meios digitais."}, {"c": "dou-paragraph", "t": "1.6 Tipografia do Selo"}, {"c": "dou-paragraph", "t": "A identidade tipográfica é essencial para garantir a clareza e a consistência visual do Selo Verde Brasil. Para títulos e elementos de destaque, a fonte principal adotada é a Inter. Já para os textos corridos, a fonte definida é a Montserrat. A Figura 5 ilustra as fontes utilizadas na tipografia."}, {"c": "dou-paragraph", "t": "1.7 Arquivo Eletrônico do Selo"}, {"c": "dou-paragraph", "t": "O arquivo eletrônico do Selo Verde Brasil pode ser solicitado pelo endereço eletrônico: selos.dconf@inmetro.gov.br."}, {"c": "nota", "t": "N. da Codou: Republicada por ter saído, no DOU nº 176-D, de 17/09/2026, Seção 1, pág. 7, com incorreção do original."}]});